<?php use App\Core\Csrf; use App\Helpers\ViewHelper; ?><article class="book-card"><a class="book-cover" href="/books/<?= ViewHelper::escape($book['slug']) ?>"><img src="/assets/images/book-placeholder.svg" alt="Bìa sách <?= ViewHelper::escape($book['title']) ?>" loading="lazy"></a><div class="book-info"><h3><a title="<?= ViewHelper::escape($book['title']) ?>" href="/books/<?= ViewHelper::escape($book['slug']) ?>"><?= ViewHelper::escape($book['title']) ?></a></h3><p class="book-author"><?= ViewHelper::escape($book['author']) ?></p><p class="book-price"><?= ViewHelper::money($book['price']) ?></p><?php if ($book['original_price'] > $book['price']): ?><del><?= ViewHelper::money($book['original_price']) ?></del><?php endif; ?><?php if (is_array($currentUser ?? null)): ?><form class="wishlist-inline-form" method="post" action="/wishlist/add/<?= (int)$book['id'] ?>"><?= Csrf::field() ?><button class="wishlist-button" type="submit"><span class="material-symbols-outlined" aria-hidden="true">favorite_border</span>Lưu yêu thích</button></form><?php endif; ?></div></article>
